import { useState, useEffect } from 'react';
import { BrowserRouter, Routes, Route, Link, useNavigate, useParams } from 'react-router-dom';
import axios from 'axios';

function useAPI({ apiPath }) {
    const [result, setResult] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchUserId = async () => {
            try {
                const response = await axios.get(apiPath);

                console.log("DEBUG: Raw response:", response);
                console.log("DEBUG: Response data:", response.data);

                setResult(response.data);
            } catch(err) {
                console.error("Error:", err);
                setResult(0);
            } finally {
                setLoading(false);
            }
        }

        fetchUserId();
    }, [])

    return {result, loading};
}


function NavigationButton({ path, title }) {
    const navigate = useNavigate();

    const handleClick = () => {
        navigate(path);
    };

    return (
        <button 
            className="Navigation-button"
            onClick={handleClick}
        >
            {title}
        </button>
    );
}

function LoginButton({ path, title }) {
    const navigate = useNavigate();

    const handleClick = () => {
        window.location.href = `https://skilled-gazelle-wildly.ngrok-free.app${path}`;
    }

    return (
        <button 
            className="Navigation-button"
            onClick={handleClick}
        >
            {title}
        </button>
    );
}

export function Home() {
    const {result, loading} = useAPI("/api/user_id");

    if(loading) {
        return <div className="Button-holder">...Loading</div>;
    }

    return (
        <div className="Button-holder">
            <NavigationButton
            title="Play"
            path="/hub"
            />

            { result?.userId > 0 ?
                (
                    <NavigationButton
                    title="View Profile"
                    color="#1a9c2a"
                    path={"/profile/"+result.userId}
                    />
                ) : (
                    <NavigationButton
                    title="Login"
                    color="#1a9c2a"
                    path="/login"
                    />
                )
            }


            <NavigationButton
            title="Leaderboard"
            color="#1a9c2a"
            path="/leaderboard"
            />

            <NavigationButton
            title="About"
            color="#aa3c3a"
            path="/about"
            />
        </div>
    )

}

export function Hub() {
    return (
        <div className="Button-holder">
            <NavigationButton
            title="Normal 180s"
            path="/play?game_mode=0"
            />

            <NavigationButton
            title="Normal 300s"
            path="/play?game_mode=1"
            />

            <NavigationButton
            title="Normal 600s"
            path="/play?game_mode=2"
            />
        </div>
    );
}

export function Login() {
    return (
        <div className="Button-holder">
            <LoginButton
            title="Login With Google"
            path="/api/auth/google"
            />

            <LoginButton
            title="Login With GitHub"
            path="/api/auth/github"
            />
        </div>
    );
}

